131	export const handleTrajectoryToolUsed = (params: AssertionParams): GradingResult => {
132	  const trace = getTraceOrThrow(params);
133	  const steps = extractTrajectorySteps(trace).filter((step) => step.type === 'tool');
134	  const expected = resolveToolMatchers(params.renderedValue ?? params.assertion.value);
135	
136	  if (expected.kind === 'list') {
137	    if (expected.matchers.length === 0) {
138	      throw new Error('trajectory:tool-used assertion requires at least one expected tool');
139	    }
140	
141	    const missing = expected.matchers.filter(
142	      (matcher) => !steps.some((step) => matchesTrajectoryStep(step, matcher)),
143	    );
144	    const matched = expected.matchers.filter((matcher) =>
145	      steps.some((step) => matchesTrajectoryStep(step, matcher)),
146	    );
147	
148	    const pass = params.inverse ? matched.length === 0 : missing.length === 0;
149	    const actualTools = steps.map(formatTrajectoryStep);
150	
151	    const expectedTools = expected.matchers.map(
152	      (matcher) => matcher.pattern || matcher.name || '*',
153	    );
154	
155	    let reason: string;
156	    if (params.inverse) {
157	      reason = pass
158	        ? `Forbidden tool(s) were not used: ${expectedTools.join(', ')}`
159	        : `Forbidden tool(s) were used: ${matched
160	            .map((matcher) => matcher.pattern || matcher.name || '*')
161	            .join(', ')}. Actual tools: ${formatStepList(actualTools)}`;
162	    } else if (pass) {
163	      reason = `Observed required tool(s): ${expectedTools.join(', ')}. Actual tools: ${formatStepList(actualTools)}`;
164	    } else {
165	      const missingTools = missing.map((matcher) => matcher.pattern || matcher.name || '*');
166	      reason = `Missing required tool(s): ${missingTools.join(', ')}. Actual tools: ${formatStepList(actualTools)}`;
167	    }
168	
169	    return {
170	      pass,
171	      score: pass ? 1 : 0,
172	      reason,
173	      assertion: params.assertion,
174	    };
175	  }
176	
177	  const matcher = expected.matcher;
178	  const min = matcher.min ?? 1;
179	  const max = matcher.max;
180	  if (!matcher.pattern && !matcher.name) {
181	    throw new Error(
182	      'trajectory:tool-used assertion object must include a name or pattern property',
183	    );
184	  }
185	
186	  const matchingSteps = steps.filter((step) => matchesTrajectoryStep(step, matcher));
187	  const count = matchingSteps.length;
188	  const basePass = count >= min && (max === undefined || count <= max);
189	  const pass = applyInverse(basePass, params.inverse);
190	  const matcherLabel = matcher.pattern || matcher.name || '*';
191	
192	  let reason = `Matched tool "${matcherLabel}" ${count} time(s)`;
193	  if (max === undefined) {
194	    reason += ` (expected at least ${min})`;
195	  } else {
196	    reason += ` (expected ${min}-${max})`;
197	  }
198	  if (matchingSteps.length > 0) {
199	    reason += `. Matches: ${matchingSteps.map(formatTrajectoryStep).join(', ')}`;
200	  }
201	
202	  if (params.inverse) {
203	    reason = basePass
204	      ? `Tool "${matcherLabel}" matched ${count} time(s), which violates the inverse assertion`
205	      : `Tool "${matcherLabel}" did not satisfy the forbidden match condition`;
206	  }
207	
208	  return {
209	    pass,
210	    score: pass ? 1 : 0,
211	    reason,
212	    assertion: params.assertion,
213	  };
214	};
