38	export function cosineSimilarity(vecA: number[], vecB: number[]): number {
39	  if (vecA.length !== vecB.length) {
40	    throw new Error('Vectors must be of equal length');
41	  }
42	  const dotProduct = vecA.reduce((acc, val, idx) => acc + val * vecB[idx], 0);
43	  const vecAMagnitude = Math.sqrt(vecA.reduce((acc, val) => acc + val * val, 0));
44	  const vecBMagnitude = Math.sqrt(vecB.reduce((acc, val) => acc + val * val, 0));
45	  if (vecAMagnitude === 0 || vecBMagnitude === 0) {
46	    return 0;
47	  }
48	  return dotProduct / (vecAMagnitude * vecBMagnitude);
49	}
