51	export function dotProduct(vecA: number[], vecB: number[]): number {
52	  if (vecA.length !== vecB.length) {
53	    throw new Error('Vectors must be of equal length');
54	  }
55	  return vecA.reduce((acc, val, idx) => acc + val * vecB[idx], 0);
56	}
57	
58	export function euclideanDistance(vecA: number[], vecB: number[]): number {
59	  if (vecA.length !== vecB.length) {
60	    throw new Error('Vectors must be of equal length');
61	  }
62	  const sumSquaredDiff = vecA.reduce((acc, val, idx) => {
63	    const diff = val - vecB[idx];
64	    return acc + diff * diff;
65	  }, 0);
66	  return Math.sqrt(sumSquaredDiff);
67	}
