 * Build a grader transport/parse failure result. These represent cases where
 * the grader could not be evaluated at all (bad output shape, unparseable JSON),
 * as opposed to a legitimate low-scoring grade. They are tagged with
 * `metadata.graderError` so callers that support inverse semantics (e.g.
 * `not-llm-rubric`) propagate them verbatim instead of flipping pass/score.
 */
function graderFail(
  reason: string,
  tokensUsed?: ProviderResponse['tokenUsage'],
): Omit<GradingResult, 'assertion'> {
  return {
    ...fail(reason, tokensUsed),
    metadata: { graderError: true },
  };
}

function parseJsonGradingResponse(
  label: string,
  resp: ProviderResponse,
): { parsed?: Partial<GradingResult>; failure?: Omit<GradingResult, 'assertion'> } {
  let jsonObjects: unknown[] = [];
  if (typeof resp.output === 'string') {
    try {
      jsonObjects = extractJsonObjects(resp.output);
      if (jsonObjects.length === 0) {
        return {
          failure: graderFail(`Could not extract JSON from ${label} response`, resp.tokenUsage),
        };
      }
    } catch (err) {
      return {
        failure: graderFail(
          `${label} produced malformed response: ${err}\n\n${resp.output}`,
          resp.tokenUsage,
        ),
      };
    }
  } else if (
    typeof resp.output === 'object' &&
    resp.output !== null &&
    !Array.isArray(resp.output)
  ) {
    jsonObjects = [resp.output];
  } else {
    return {
      failure: graderFail(
        `${label} produced malformed response - output must be string or object. Output: ${JSON.stringify(resp.output)}`,
        resp.tokenUsage,
      ),
    };
  }

  const parsed = jsonObjects[0];
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    return {
      failure: graderFail(
        `${label} produced malformed response. We were not able to parse the response as JSON. Output: ${JSON.stringify(resp.output)}`,
        resp.tokenUsage,
      ),
    };
  }

  return { parsed: parsed as Partial<GradingResult> };
